const storageKey="control-de-polizas",form=document.querySelector("#policy-form"),list=document.querySelector("#policy-list"),template=document.querySelector("#policy-template"),summary=document.querySelector("#summary"),message=document.querySelector("#message"),emptyState=document.querySelector("#empty-state"),clearAll=document.querySelector("#clear-all");let policies=loadPolicies();function loadPolicies(){try{const e=JSON.parse(localStorage.getItem(storageKey));return Array.isArray(e)?e:[]}catch(e){return console.error("No se pudieron cargar las pólizas guardadas.",e),[]}}function savePolicies(){localStorage.setItem(storageKey,JSON.stringify(policies))}function formatDate(e){return new Intl.DateTimeFormat("es-MX",{dateStyle:"medium"}).format(new Date(`${e}T00:00:00`))}function formatAmount(e){return new Intl.NumberFormat("es-MX",{style:"currency",currency:"MXN"}).format(e)}function render(){list.replaceChildren(),policies.forEach(e=>{const t=template.content.cloneNode(!0),r=t.querySelector("tr"),o=t.querySelector(".delete");r.dataset.id=e.id,t.querySelector(".number").textContent=e.number,t.querySelector(".insured").textContent=e.insured,t.querySelector(".policy-type").textContent=e.type,t.querySelector(".insurer").textContent=e.insurer,t.querySelector(".expiration").textContent=formatDate(e.expiration),t.querySelector(".amount").textContent=formatAmount(e.amount),o.setAttribute("aria-label",`Eliminar póliza ${e.number}`),list.append(t)}),summary.textContent=1===policies.length?"1 póliza registrada":`${policies.length} pólizas registradas`,emptyState.hidden=policies.length>0}form.addEventListener("submit",e=>{e.preventDefault();const t=new FormData(form),r=document.querySelector("#policy-number").value.trim(),o=document.querySelector("#insurer").value.trim(),n=document.querySelector("#insured").value.trim(),a=t.get("policy-type"),i=document.querySelector("#expiration").value,l=Number(document.querySelector("#insured-amount").value);!(r&&o&&n&&a&&i)||Number.isNaN(l)||l<0?message.textContent="Completa correctamente todos los datos de la póliza.":(policies.unshift({id:crypto.randomUUID(),number:r,insurer:o,insured:n,type:a,expiration:i,amount:l}),savePolicies(),form.reset(),message.textContent="",render(),document.querySelector("#policy-number").focus())}),list.addEventListener("click",e=>{if(!e.target.matches(".delete"))return;const t=e.target.closest("tr").dataset.id;policies=policies.filter(e=>e.id!==t),savePolicies(),render()}),clearAll.addEventListener("click",()=>{policies.length?(policies=[],savePolicies(),message.textContent="",render()):message.textContent="No hay pólizas para eliminar."}),render();